import { D, toMoneyString } from '@/lib/finance';
import {
  advanceDays,
  CATEGORIZABLE,
  categorize,
  chargeSurpriseSubscription,
  completeMission,
  createPocket,
  createWallet,
  moveToPocket,
  setSubscription,
  setTwoFactor,
  setYieldMode,
} from './engine';
import type { WalletState } from './types';

/**
 * Demo states of the portfolio (CLAUDE.md 5.0 and 7): Diego at level 2 and Mariana at level 6,
 * generated by replaying a script of actions through the engine (wallet-engine.md, section 12),
 * never written by hand. The same script always gives the same state.
 */
export const DEMO_DAYS = { 'p-diego': 12, 'p-mariana': 154 } as const;

export const POCKET_SAVINGS = 'pocket-savings';
export const POCKET_EMERGENCY = 'pocket-emergency';
export const POCKET_GOAL = 'pocket-goal-vacations';

/** Advances to a day of the simulation (never backwards). */
const goTo = (state: WalletState, day: number) => (day > state.day ? advanceDays(state, day - state.day) : state);

/** The person confirms the suggested category of every expense so far (Mariana does it every month). */
function confirmCategories(state: WalletState): WalletState {
  let next = state;
  for (const m of state.movements) {
    if (!m.category && m.suggestedCategory && CATEGORIZABLE.includes(m.type)) next = categorize(next, m.id, m.suggestedCategory);
  }
  return next;
}

const percentOf = (amount: string, percent: string) => toMoneyString(D(amount).times(percent));

/** Level 0 and mission 1 (5.3): security, first salary, 20 % into "Ahorro" (D-53), the surprise subscription (D-55). */
function openAndFirstSalary(personId: string): WalletState {
  let s = createWallet(personId);
  s = setTwoFactor(s, true);
  s = completeMission(s, 'mission-security');
  s = advanceDays(s, 1); // day 1: salary
  s = createPocket(s, { id: POCKET_SAVINGS, name: 'Ahorro' });
  s = moveToPocket(s, POCKET_SAVINGS, percentOf(s.salary, '0.2'));
  s = chargeSurpriseSubscription(s);
  return completeMission(s, 'mission-1');
}

export function buildDiego(): WalletState {
  let s = openAndFirstSalary('p-diego');
  // Diego kept the subscription (a "gasto hormiga" he still has to decide on) and started categorizing.
  s = goTo(s, DEMO_DAYS['p-diego']);
  let confirmed = 0;
  for (const m of s.movements) {
    if (confirmed >= 4) break;
    if (m.suggestedCategory && CATEGORIZABLE.includes(m.type)) {
      s = categorize(s, m.id, m.suggestedCategory);
      confirmed += 1;
    }
  }
  return s;
}

export function buildMariana(): WalletState {
  let s = openAndFirstSalary('p-mariana');
  s = setSubscription(s, false); // she spotted and cancelled it in mission 1
  // Level 2 missions, done in the first month.
  for (const id of ['mission-2', 'mission-3', 'mission-6']) s = completeMission(s, id);
  s = goTo(s, 30); // month 0 closes: the first month in green (level 3, mission 7)
  s = confirmCategories(s);
  s = completeMission(s, 'mission-7');

  // Level 4 from day 31: emergency fund (3 months as goal) and a savings goal.
  s = goTo(s, 31);
  s = createPocket(s, { id: POCKET_EMERGENCY, name: 'Fondo de emergencia', isEmergencyFund: true, goal: '1950000.00' });
  s = createPocket(s, { id: POCKET_GOAL, name: 'Vacaciones de invierno', goal: '2138641.00' });
  s = completeMission(s, 'mission-emergency-fund');

  // Every month, on salary day: 25 % to the emergency fund and 5 % to the goal.
  for (let month = 1; month <= 5; month += 1) {
    s = goTo(s, month * 30 + 1);
    s = moveToPocket(s, POCKET_EMERGENCY, percentOf(s.salary, '0.25'));
    s = moveToPocket(s, POCKET_GOAL, percentOf(s.salary, '0.05'));
    if (month === 3) s = completeMission(s, 'mission-debts'); // level 5 (mission 5 is still pending, as in the seed)
    if (month === 4) {
      // Level 6 (Rendir): mission 4 "¿Cuenta o fondo?": she chooses the remunerated account on day 125
      // and, after 30 days, explains the difference (completed on day 151, as in the seed).
      s = goTo(s, 125);
      s = setYieldMode(s, 'remunerated');
    }
    if (month === 5) s = completeMission(s, 'mission-4');
    s = confirmCategories(s);
  }
  s = goTo(s, DEMO_DAYS['p-mariana']);
  return confirmCategories(s);
}

export function buildDemoWallet(personId: string): WalletState | null {
  if (personId === 'p-diego') return buildDiego();
  if (personId === 'p-mariana') return buildMariana();
  return null;
}
